export type ProviderIconKey = keyof typeof PROVIDER_ICONS;

function toCamelCase(iconId: string) {
  const parts = iconId.split('-');

  return (
    parts[0] +
    parts
      .slice(1)
      .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
      .join('')
  );
}

function toKebabCase(iconId: string) {
  return iconId
    .replace(/([a-z0-9])([A-Z])/g, '$1-$2')
    .replace(/([A-Z]+)([A-Z][a-z])/g, '$1-$2')
    .toLowerCase();
}

export function resolveProviderAssetIcon(iconId: string): IconSource | undefined {
  if (!iconId) return undefined;

  const icons = PROVIDER_ICONS as Record<string, IconSource>;
  const key = PROVIDER_ID_ALIASES[iconId] ?? iconId;

  return (
    icons[key as ProviderIconKey] ??
    icons[toKebabCase(key) as ProviderIconKey] ??
    icons[toCamelCase(key) as ProviderIconKey]
  );
}
export function resolveProviderIcon(iconId: string): IconSource | undefined {
  if (iconId === 'opencode') return resolveGeneralIcon('open-code');

  return resolveProviderAssetIcon(iconId);
}
